-- Every esports roster the site has published, recovered from the git history of this
-- repository and of the frontend repository that preceded it.
--
-- A season is a stretch of play, two to a board year; a roster is what a team fielded in one
-- of them. Where a page went untouched between seasons the roster that stood is the roster
-- recorded, because that is what the site showed.
--
-- Real names are imported for identification and are not published: the public endpoint
-- returns handles alone. Names came off the site deliberately, and putting one back is a
-- decision for the member it belongs to.
--
-- The rows stage in a temporary table and insert set-based from there. Idempotent throughout,
-- so a rerun adds only what is missing.

CREATE TEMPORARY TABLE esports_import (
    game         VARCHAR(32)  NOT NULL,
    team         VARCHAR(128) NOT NULL,
    image        VARCHAR(255) NULL,
    season       VARCHAR(64)  NOT NULL,
    season_start DATE         NOT NULL,
    season_end   DATE         NOT NULL,
    handle       VARCHAR(128) NOT NULL,
    team_role    VARCHAR(16)  NOT NULL,
    display_name VARCHAR(128) NULL,
    sort_index   INT          NOT NULL
) ENGINE=Memory DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;







-- Seasons, teams, rosters: each read out of the staging table, each guarded so a
-- rerun is a no-op rather than a duplicate.
SELECT DISTINCT i.season, i.season_start, i.season_end
FROM esports_import i
WHERE NOT EXISTS (SELECT 1 FROM season s WHERE s.name = i.season AND s.deleted_at = '9999-12-31 23:59:59.000000');

-- The recovered rows carry the filename the old page drew the team on. It is read into the
-- staging table and goes no further: a team's picture is an upload the site ships, put on the
-- team once the application is up and there is somewhere to put the bytes.
SELECT DISTINCT i.game, i.team
FROM esports_import i
WHERE NOT EXISTS (SELECT 1 FROM team t WHERE t.game = i.game AND t.name = i.team AND t.deleted_at = '9999-12-31 23:59:59.000000');

SELECT t.id, s.id, i.handle, i.team_role, i.display_name, i.sort_index
FROM esports_import i
JOIN team t ON t.game = i.game AND t.name = i.team AND t.deleted_at = '9999-12-31 23:59:59.000000'
JOIN season s ON s.name = i.season AND s.deleted_at = '9999-12-31 23:59:59.000000'
WHERE NOT EXISTS (
    SELECT 1 FROM team_roster_entry e
    WHERE e.team_id = t.id AND e.season_id = s.id AND e.handle = i.handle
      AND e.deleted_at = '9999-12-31 23:59:59.000000');

DROP TEMPORARY TABLE esports_import;

-- Members: one join on an exact name, built the way the site writes one, prefix and
-- all. A name matching nobody, or more than one person, leaves the entry standing
-- under its handle for an admin to resolve.
UPDATE team_roster_entry e
JOIN (
    SELECT TRIM(CONCAT_WS(' ', u.first_name, u.prefix, u.last_name)) AS full_name,
           MIN(u.id) AS user_id
    FROM users u
    WHERE u.deleted_at = '9999-12-31 23:59:59.000000'
    GROUP BY full_name
    HAVING COUNT(*) = 1
) m ON m.full_name = e.display_name
SET e.user_id = m.user_id
WHERE e.user_id IS NULL AND e.display_name IS NOT NULL AND e.deleted_at = '9999-12-31 23:59:59.000000';

-- A linked member's handle becomes theirs for that game, so a rename later lands on
-- every season at once. The most recent season they played is the one that names them.
SELECT x.user_id, x.game, x.handle
FROM (
    SELECT e.user_id, t.game, e.handle,
           ROW_NUMBER() OVER (
               PARTITION BY e.user_id, t.game ORDER BY s.start_date DESC, e.id DESC
           ) AS rn
    FROM team_roster_entry e
    JOIN team t ON t.id = e.team_id
    JOIN season s ON s.id = e.season_id
    WHERE e.user_id IS NOT NULL AND e.deleted_at = '9999-12-31 23:59:59.000000'
) x
WHERE x.rn = 1
  AND NOT EXISTS (
    SELECT 1 FROM user_game_account a
    WHERE a.user_id = x.user_id AND a.game = x.game AND a.deleted_at = '9999-12-31 23:59:59.000000');
